import asyncio
from playwright.async_api import async_playwright
H='http://127.0.0.1:8010'
async def main():
 async with async_playwright() as pw:
  b=await pw.chromium.launch(executable_path='/usr/bin/chromium',args=['--no-sandbox'])
  for width in [1280,390]:
   c=await b.new_context(viewport={'width':width,'height':844});await c.route('https://**/*',lambda r:r.abort());p=await c.new_page();errors=[];p.on('pageerror',lambda e:errors.append(str(e)));await p.goto(H+'/login');await p.locator('input[type=text]').first.fill('TESTADMIN');await p.locator('input[type=password]').fill('PruebaSegura123!');await p.get_by_role('button',name='Iniciar Sesión',exact=True).click();await p.wait_for_function('window.SICIPWorkflows&&window.SICIPCentral?.user')
   if width==390:await p.locator('[aria-controls=sicip-sidebar]').click()
   await p.locator('[data-sicip-depto-btn]').click();await p.get_by_role('button',name='Control de Faltas',exact=False).click();box=p.locator('[data-faltas-ranking]');await box.locator('[data-ranking-results] tbody tr').first.wait_for();assert await box.locator('[data-ranking-results] tbody tr').count()==10;assert '13' in await box.locator('[data-ranking-results] tbody tr').first.inner_text();form=box.locator('form');await form.locator('[name=mes]').select_option('7');await p.wait_for_function("document.querySelector('[data-ranking-results]')?.textContent.includes('TESTUSER')");assert await box.locator('[data-ranking-results] tbody tr').count()==1;await form.locator('[name=mes]').select_option('0');await form.locator('[name=categoria]').select_option('Enfermería');await p.wait_for_function("document.querySelectorAll('[data-ranking-results] tbody tr').length===6");await form.locator('[name=unidad]').select_option('U1');await form.locator('[name=q]').fill('RANK10');await p.wait_for_function("document.querySelectorAll('[data-ranking-results] tbody tr').length===1&&document.querySelector('[data-ranking-results]').textContent.includes('RANK10')");assert await form.locator('[name=q]').get_attribute('inputmode')=='text';await box.get_by_role('button',name='Ver faltas',exact=True).click();await p.locator('#sf-result').get_by_role('heading',name='Faltas por quincena').wait_for();assert await p.locator('#sf-result .sicip-flow-kpi b').nth(1).inner_text()=='12';assert await p.evaluate('document.documentElement.scrollWidth<=innerWidth+1');assert not errors,errors;await p.screenshot(path='/tmp/ranking-'+str(width)+'.png',full_page=True);await c.close();print('Control de Faltas '+str(width)+': top 10, mes/categoría/unidad/nombre y consulta individual correctos.',flush=True)
  await b.close()
asyncio.run(main())
